store("inspect21",`function inspect(raw){
const s=raw.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n"), cols="ABCDEFGHJ", b={};
for(const line of s.split("\\n")){const m=line.match(/^\\s*([1-9])\\s+([XO.](?:\\s+[XO.]){8})\\s+[1-9]/);if(m)m[2].trim().split(/\\s+/).forEach((v,i)=>b[cols[i]+m[1]]=v);}
const ns=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([x,y])=>x>=0&&x<9&&y>=1&&y<=9).map(([x,y])=>cols[x]+y);};
const seen=new Set(), groups=[],regions=[];
for(const p of Object.keys(b)){if(seen.has(p))continue;const color=b[p],todo=[p],stones=[],lib=new Set(),borders=new Set();seen.add(p);while(todo.length){const q=todo.pop();stones.push(q);for(const n of ns(q)){if(b[n]===color&&!seen.has(n)){seen.add(n);todo.push(n);}else if(b[n]===".")lib.add(n);else if(b[n]!==color)borders.add(b[n]);}}
if(color===".")regions.push({points:stones.sort(),borders:[...borders]});else groups.push({color,stones:stones.sort(),liberties:[...lib].sort()});}
return {board:b,groups,regions};}`);
